drop policy if exists exports_owner_insert on public.exports; create policy exports_owner_insert on public.exports for insert to authenticated with check(owner_id=(select auth.uid()) and exists(select 1 from public.school_projects p where p.id=exports.project_id and p.owner_id=(select auth.uid())) and exists(select 1 from public.batches b where b.id=exports.batch_id and b.project_id=exports.project_id and b.owner_id=exports.owner_id and b.owner_id=(select auth.uid())));